INSERT INTO recipes (name, country, continent, is_african, category, slug, summary, history, difficulty, prep_time, cook_time, servings, tags, image_url, ingredients, steps) VALUES

-- SOUTH AFRICA
('Rooibos Tea', 'South Africa', 'Africa', true, 'Drinks', 'rooibos-tea-south-africa',
'South Africa''s iconic caffeine-free red bush tea - naturally sweet with a honeyed, earthy flavor.',
'Rooibos is endemic to the Cederberg mountains of the Western Cape. The Khoisan people brewed it for centuries before it became South Africa''s most exported beverage.',
'Easy', 5, 5, 4, ARRAY['drinks', 'south-african', 'tea', 'caffeine-free', 'healthy'],
'https://images.unsplash.com/photo-1571934811356-5cc061b6821f?w=800&auto=format&fit=crop',
'[{"item":"Rooibos tea leaves","quantity":"2 tbsp"},{"item":"Boiling water","quantity":"4 cups"},{"item":"Honey","quantity":"to taste"},{"item":"Milk","quantity":"optional"},{"item":"Lemon slice","quantity":"optional"}]',
'[{"step":1,"instruction":"Bring water to a rolling boil."},{"step":2,"instruction":"Add rooibos tea leaves. Steep for 5-7 minutes (it never becomes bitter, so longer is fine)."},{"step":3,"instruction":"Strain into cups. Add honey if desired."},{"step":4,"instruction":"Serve with milk for a traditional South African experience, or with lemon for a lighter version."}]'),

('Vetkoek', 'South Africa', 'Africa', true, 'Breakfast', 'vetkoek-south-africa',
'Deep-fried bread rolls, crispy outside and fluffy inside - filled with curried mince for breakfast or jam for a sweet treat.',
'Vetkoek (fat cake) has Dutch colonial origins and has become a beloved South African street food. It bridges Afrikaner and Black South African culinary traditions.',
'Easy', 60, 15, 8, ARRAY['breakfast', 'south-african', 'bread', 'fried', 'street-food'],
'https://images.unsplash.com/photo-1567364816519-cbc9c4a0a736?w=800&auto=format&fit=crop',
'[{"item":"Bread flour","quantity":"3 cups"},{"item":"Yeast","quantity":"1 packet"},{"item":"Sugar","quantity":"1 tbsp"},{"item":"Salt","quantity":"1 tsp"},{"item":"Warm water","quantity":"1 cup"},{"item":"Vegetable oil","quantity":"for frying"},{"item":"Curried mince","quantity":"for filling"},{"item":"Apricot jam","quantity":"for sweet option"}]',
'[{"step":1,"instruction":"Mix flour, yeast, sugar, and salt. Add warm water and knead into soft dough."},{"step":2,"instruction":"Cover and let rise 1 hour until doubled."},{"step":3,"instruction":"Divide into balls. Let rest 10 minutes."},{"step":4,"instruction":"Deep fry in hot oil until golden brown on both sides, about 5 minutes."},{"step":5,"instruction":"Drain on paper towels. Slice open and fill with curried mince or jam."}]'),

('Bobotie', 'South Africa', 'Africa', true, 'Lunch', 'bobotie-south-africa',
'Cape Malay spiced minced meat bake topped with savory egg custard - South Africa''s national dish.',
'Bobotie has roots in the Cape Malay community, blending Indonesian spices brought by slaves with local cooking. It has been documented since 1609 and is considered South Africa''s national dish.',
'Medium', 20, 45, 6, ARRAY['lunch', 'south-african', 'cape-malay', 'mince', 'custard'],
'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=800&auto=format&fit=crop',
'[{"item":"Beef mince","quantity":"750g"},{"item":"Onions","quantity":"2","note":"chopped"},{"item":"Bread","quantity":"2 slices","note":"soaked in milk"},{"item":"Curry powder","quantity":"2 tbsp"},{"item":"Turmeric","quantity":"1 tsp"},{"item":"Apricot jam","quantity":"2 tbsp"},{"item":"Raisins","quantity":"1/4 cup"},{"item":"Almonds","quantity":"1/4 cup","note":"slivered"},{"item":"Eggs","quantity":"3"},{"item":"Milk","quantity":"1 cup"},{"item":"Bay leaves","quantity":"4"},{"item":"Salt","quantity":"to taste"}]',
'[{"step":1,"instruction":"Sauté onions. Add mince and brown. Add curry powder, turmeric, jam, raisins, and soaked bread."},{"step":2,"instruction":"Season with salt. Transfer to a baking dish. Press down firmly."},{"step":3,"instruction":"Whisk eggs with milk. Pour over the mince. Place bay leaves on top."},{"step":4,"instruction":"Bake at 350°F for 35-40 minutes until custard is set and golden."},{"step":5,"instruction":"Serve with yellow rice, sambals, and chutney."}]'),

('Potjiekos', 'South Africa', 'Africa', true, 'Dinner', 'potjiekos-south-africa',
'South African slow-cooked layered stew prepared in a three-legged cast iron pot over open coals.',
'Potjiekos has been a social cooking tradition since the Voortrekker era. The three-legged pot is a symbol of South African outdoor culture, and the dish is never stirred - layers cook together slowly.',
'Medium', 30, 180, 8, ARRAY['dinner', 'south-african', 'stew', 'outdoor', 'slow-cooked'],
'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=800&auto=format&fit=crop',
'[{"item":"Lamb or beef","quantity":"1 kg","note":"cubed"},{"item":"Potatoes","quantity":"4","note":"quartered"},{"item":"Carrots","quantity":"3","note":"chunked"},{"item":"Cabbage","quantity":"1/4 head"},{"item":"Green beans","quantity":"1 cup"},{"item":"Onion","quantity":"2","note":"sliced"},{"item":"Garlic","quantity":"4 cloves"},{"item":"Tomato paste","quantity":"2 tbsp"},{"item":"Red wine","quantity":"1 cup"},{"item":"Beef stock","quantity":"1 cup"},{"item":"Mixed herbs","quantity":"2 tsp"},{"item":"Oil","quantity":"3 tbsp"},{"item":"Salt and pepper","quantity":"to taste"}]',
'[{"step":1,"instruction":"Heat oil in the potjie pot. Brown meat in batches. Remove."},{"step":2,"instruction":"Sauté onions and garlic. Add tomato paste."},{"step":3,"instruction":"Layer: meat first, then carrots, potatoes, green beans, and cabbage on top."},{"step":4,"instruction":"Pour wine and stock over. Add herbs, salt, and pepper."},{"step":5,"instruction":"Cover tightly. Cook over low coals for 2.5-3 hours. DO NOT stir."},{"step":6,"instruction":"Serve directly from the pot with rice or bread."}]'),

('Amarula Cream Cocktail', 'South Africa', 'Africa', true, 'Drinks', 'amarula-cream-south-africa',
'Decadent South African cocktail with Amarula cream liqueur, milk, and ice - smooth and indulgent.',
'Amarula is made from the fruit of the marula tree, native to Southern Africa. Elephants famously feast on the fallen fruit. The liqueur was first produced in 1989 and is now enjoyed worldwide.',
'Easy', 5, 0, 2, ARRAY['drinks', 'south-african', 'cocktail', 'cream', 'marula'],
'https://images.unsplash.com/photo-1513558161293-cdaf765ed2fd?w=800&auto=format&fit=crop',
'[{"item":"Amarula cream liqueur","quantity":"120ml"},{"item":"Milk","quantity":"60ml"},{"item":"Vanilla ice cream","quantity":"2 scoops","note":"optional"},{"item":"Ice","quantity":"1 cup"},{"item":"Cocoa powder","quantity":"for dusting"}]',
'[{"step":1,"instruction":"Add Amarula, milk, and ice to a blender."},{"step":2,"instruction":"Add ice cream for a frozen version if desired."},{"step":3,"instruction":"Blend until smooth."},{"step":4,"instruction":"Pour into glasses. Dust with cocoa powder. Serve immediately."}]'),

-- ZIMBABWE
('Maheu', 'Zimbabwe', 'Africa', true, 'Drinks', 'maheu-zimbabwe',
'Zimbabwean creamy fermented maize drink - thick, tangy, and naturally sweet.',
'Maheu is Zimbabwe''s traditional non-alcoholic fermented drink, consumed as both a refreshment and a meal supplement. It has become commercially popular across Southern Africa.',
'Easy', 20, 20, 6, ARRAY['drinks', 'zimbabwean', 'fermented', 'maize', 'probiotic'],
'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=800&auto=format&fit=crop',
'[{"item":"Cornmeal","quantity":"1 cup"},{"item":"Water","quantity":"4 cups"},{"item":"Sugar","quantity":"1/3 cup"},{"item":"Millet malt","quantity":"2 tbsp"},{"item":"Vanilla","quantity":"1 tsp","note":"optional"}]',
'[{"step":1,"instruction":"Mix cornmeal with cold water. Boil 2 cups water and add the paste."},{"step":2,"instruction":"Cook for 10 minutes, stirring constantly until thick porridge forms."},{"step":3,"instruction":"Let cool to lukewarm. Add millet malt and sugar."},{"step":4,"instruction":"Transfer to a container. Cover loosely and ferment 24-48 hours."},{"step":5,"instruction":"Stir well. Add vanilla if using. Serve chilled."}]'),

('Sadza ne Nyama', 'Zimbabwe', 'Africa', true, 'Dinner', 'sadza-ne-nyama-zimbabwe',
'Zimbabwean stiff cornmeal porridge served with savory beef stew - the everyday dinner across the nation.',
'Sadza is the staple food of Zimbabwe, eaten at nearly every dinner. "Sadza ne nyama" (sadza with meat) is the most popular combination, representing comfort and home.',
'Easy', 15, 40, 4, ARRAY['dinner', 'zimbabwean', 'cornmeal', 'beef', 'staple'],
'https://images.unsplash.com/photo-1574484284002-952d92456975?w=800&auto=format&fit=crop',
'[{"item":"White cornmeal","quantity":"2 cups"},{"item":"Water","quantity":"4 cups"},{"item":"Beef","quantity":"500g","note":"cubed"},{"item":"Tomatoes","quantity":"3","note":"diced"},{"item":"Onion","quantity":"1","note":"chopped"},{"item":"Garlic","quantity":"2 cloves"},{"item":"Vegetable oil","quantity":"2 tbsp"},{"item":"Salt","quantity":"to taste"}]',
'[{"step":1,"instruction":"For sadza: Boil water. Mix cornmeal with cold water to form a paste. Stir paste into boiling water."},{"step":2,"instruction":"Cook on low heat, adding more cornmeal gradually, stirring vigorously until very thick and pulls from the pot."},{"step":3,"instruction":"For stew: Brown beef in oil. Add onion and garlic."},{"step":4,"instruction":"Add tomatoes and salt. Simmer 25-30 minutes until beef is tender and sauce thick."},{"step":5,"instruction":"Serve sadza on a plate with stew on the side. Eat with hands."}]'),

-- ZAMBIA
('Munkoyo', 'Zambia', 'Africa', true, 'Drinks', 'munkoyo-zambia',
'Zambian traditional fermented corn drink flavored with munkoyo roots - refreshing and probiotic-rich.',
'Munkoyo is Zambia''s most popular traditional drink, named after the wild root used to ferment it. Every family has their own recipe, and it is sold extensively by street vendors.',
'Easy', 30, 20, 8, ARRAY['drinks', 'zambian', 'fermented', 'corn', 'traditional'],
'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=800&auto=format&fit=crop',
'[{"item":"Cornmeal","quantity":"1 cup"},{"item":"Munkoyo roots","quantity":"handful","note":"or substitute with ginger and malt"},{"item":"Sugar","quantity":"1/4 cup"},{"item":"Water","quantity":"4 cups"}]',
'[{"step":1,"instruction":"Boil water and stir in cornmeal. Cook until thick porridge forms."},{"step":2,"instruction":"Let cool to lukewarm. Add crushed munkoyo roots."},{"step":3,"instruction":"Cover and ferment 24-48 hours until tangy and bubbly."},{"step":4,"instruction":"Strain. Add sugar to taste. Serve chilled."}]'),

('Ifisashi', 'Zambia', 'Africa', true, 'Lunch', 'ifisashi-zambia',
'Zambian vegetables simmered in a rich peanut sauce - a nutritious vegetarian lunch served with nshima.',
'Ifisashi is one of Zambia''s most beloved dishes, showcasing the country''s love of peanut-based sauces. It is often made during the rainy season when leafy greens are abundant.',
'Easy', 15, 25, 4, ARRAY['lunch', 'zambian', 'peanut', 'vegetarian', 'greens'],
'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=800&auto=format&fit=crop',
'[{"item":"Mixed greens (rape, pumpkin leaves)","quantity":"500g","note":"chopped"},{"item":"Peanut butter","quantity":"1/2 cup"},{"item":"Tomatoes","quantity":"3","note":"diced"},{"item":"Onion","quantity":"1","note":"chopped"},{"item":"Salt","quantity":"to taste"},{"item":"Water","quantity":"1 cup"}]',
'[{"step":1,"instruction":"Sauté onion until soft. Add tomatoes and cook 5 minutes."},{"step":2,"instruction":"Add chopped greens and cook until wilted."},{"step":3,"instruction":"Dissolve peanut butter in water. Add to vegetables."},{"step":4,"instruction":"Simmer 15 minutes until sauce thickens and greens are tender."},{"step":5,"instruction":"Serve with nshima (cornmeal porridge)."}]'),

('Nshima ne Ndiwo', 'Zambia', 'Africa', true, 'Dinner', 'nshima-ne-ndiwo-zambia',
'Zambian thick cornmeal porridge with chicken and tomato relish - the national dinner.',
'Nshima is Zambia''s staple food, equivalent to ugali in East Africa. The phrase "Have you eaten nshima?" essentially means "Have you eaten?", showing its centrality to Zambian life.',
'Easy', 15, 35, 4, ARRAY['dinner', 'zambian', 'cornmeal', 'chicken', 'national-dish'],
'https://images.unsplash.com/photo-1574484284002-952d92456975?w=800&auto=format&fit=crop',
'[{"item":"White cornmeal","quantity":"2 cups"},{"item":"Water","quantity":"4 cups"},{"item":"Chicken pieces","quantity":"4"},{"item":"Tomatoes","quantity":"3","note":"diced"},{"item":"Onion","quantity":"1","note":"chopped"},{"item":"Oil","quantity":"2 tbsp"},{"item":"Salt","quantity":"to taste"}]',
'[{"step":1,"instruction":"Cook chicken with onion, tomatoes, salt, and a little water until tender and sauce thick."},{"step":2,"instruction":"For nshima: Boil water. Make cornmeal paste with cold water."},{"step":3,"instruction":"Stir paste into boiling water. Add more cornmeal until very thick."},{"step":4,"instruction":"Cook 10 minutes, stirring with a wooden spoon until it pulls from the pot."},{"step":5,"instruction":"Serve nshima shaped into a mound with chicken relish on the side."}]'),

-- MOZAMBIQUE
('Matapa', 'Mozambique', 'Africa', true, 'Lunch', 'matapa-mozambique',
'Mozambican cassava leaf stew with coconut milk, peanuts, and shrimp - a coastal lunch specialty.',
'Matapa is Mozambique''s most famous dish, combining indigenous cassava with Portuguese-introduced coconut and the bounty of the Indian Ocean coast.',
'Medium', 20, 40, 4, ARRAY['lunch', 'mozambican', 'cassava', 'coconut', 'shrimp'],
'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=800&auto=format&fit=crop',
'[{"item":"Cassava leaves","quantity":"500g","note":"ground"},{"item":"Coconut milk","quantity":"400ml"},{"item":"Shrimp","quantity":"300g","note":"peeled"},{"item":"Peanuts","quantity":"1/2 cup","note":"ground"},{"item":"Garlic","quantity":"3 cloves"},{"item":"Onion","quantity":"1"},{"item":"Salt","quantity":"to taste"},{"item":"Rice","quantity":"for serving"}]',
'[{"step":1,"instruction":"Boil ground cassava leaves for 20 minutes. Drain."},{"step":2,"instruction":"Sauté onion and garlic. Add drained cassava leaves."},{"step":3,"instruction":"Add ground peanuts and coconut milk. Stir well."},{"step":4,"instruction":"Simmer 15 minutes. Add shrimp and cook 5 more minutes."},{"step":5,"instruction":"Season with salt. Serve with white rice."}]'),

-- NAMIBIA
('Kapana', 'Namibia', 'Africa', true, 'Dinner', 'kapana-namibia',
'Namibian street-grilled beef seasoned with chili salt and served with tomato-onion relish - the nation''s street food.',
'Kapana originated in the informal markets of Namibian townships. It has become the country''s most popular street food and a symbol of Namibian informal economy culture.',
'Easy', 10, 15, 4, ARRAY['dinner', 'namibian', 'beef', 'grilled', 'street-food'],
'https://images.unsplash.com/photo-1529692236671-f1f6cf9683ba?w=800&auto=format&fit=crop',
'[{"item":"Beef","quantity":"500g","note":"thinly sliced"},{"item":"Chili salt","quantity":"2 tsp"},{"item":"Vegetable oil","quantity":"for grilling"},{"item":"Tomatoes","quantity":"2","note":"diced"},{"item":"Onion","quantity":"1","note":"diced"},{"item":"Chili flakes","quantity":"1/2 tsp"}]',
'[{"step":1,"instruction":"Season beef slices with chili salt."},{"step":2,"instruction":"Grill on a very hot flat grill or braai until charred on edges."},{"step":3,"instruction":"Mix tomatoes, onion, and chili flakes for relish."},{"step":4,"instruction":"Serve grilled beef with the fresh relish and bread."}]'),

('Oshikundu', 'Namibia', 'Africa', true, 'Drinks', 'oshikundu-namibia',
'Namibian traditional fermented millet drink from Ovambo culture - creamy and naturally probiotic.',
'Oshikundu is central to Owambo hospitality in Northern Namibia. It is the first drink offered to guests and is essential at all cultural celebrations.',
'Easy', 30, 15, 6, ARRAY['drinks', 'namibian', 'millet', 'fermented', 'owambo'],
'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=800&auto=format&fit=crop',
'[{"item":"Pearl millet flour","quantity":"1 cup"},{"item":"Sorghum malt","quantity":"2 tbsp"},{"item":"Sugar","quantity":"2 tbsp"},{"item":"Water","quantity":"4 cups"}]',
'[{"step":1,"instruction":"Make a thin porridge with millet flour and boiled water."},{"step":2,"instruction":"Cool to lukewarm. Add sorghum malt."},{"step":3,"instruction":"Cover and ferment 12-24 hours."},{"step":4,"instruction":"Add sugar. Serve slightly chilled."}]'),

-- BOTSWANA
('Seswaa', 'Botswana', 'Africa', true, 'Lunch', 'seswaa-botswana',
'Botswana''s national dish - slow-boiled beef pounded to shreds and seasoned simply with salt.',
'Seswaa is the most important dish in Tswana culture, served at every significant gathering from weddings to funerals. The extended boiling and pounding creates a uniquely tender texture.',
'Easy', 10, 180, 8, ARRAY['lunch', 'botswanan', 'beef', 'pounded', 'national-dish'],
'https://images.unsplash.com/photo-1529692236671-f1f6cf9683ba?w=800&auto=format&fit=crop',
'[{"item":"Beef (with bones)","quantity":"2 kg"},{"item":"Salt","quantity":"to taste"},{"item":"Water","quantity":"to cover"},{"item":"Pap (cornmeal porridge)","quantity":"for serving"}]',
'[{"step":1,"instruction":"Place beef in a large pot with bones. Cover with water."},{"step":2,"instruction":"Boil on medium heat for 2.5-3 hours until meat falls off the bone."},{"step":3,"instruction":"Remove bones. Using two forks or a wooden pestle, pound and shred the meat."},{"step":4,"instruction":"Season with salt. The meat should be finely shredded."},{"step":5,"instruction":"Serve with pap (cornmeal porridge) and morogo (wild spinach)."}]'),

('Magwinya', 'Botswana', 'Africa', true, 'Breakfast', 'magwinya-botswana',
'Southern African fried dough balls - golden, puffy, and served with tea for breakfast.',
'Magwinya (also called fat cakes) are a morning staple across Botswana and Southern Africa. They are sold by vendors outside schools, bus stations, and markets.',
'Easy', 60, 15, 10, ARRAY['breakfast', 'botswanan', 'fried', 'dough', 'street-food'],
'https://images.unsplash.com/photo-1567364816519-cbc9c4a0a736?w=800&auto=format&fit=crop',
'[{"item":"Flour","quantity":"3 cups"},{"item":"Yeast","quantity":"1 tsp"},{"item":"Sugar","quantity":"2 tbsp"},{"item":"Salt","quantity":"1 tsp"},{"item":"Warm water","quantity":"1.5 cups"},{"item":"Oil","quantity":"for frying"}]',
'[{"step":1,"instruction":"Mix flour, yeast, sugar, and salt. Add warm water and knead until smooth."},{"step":2,"instruction":"Cover and let rise 1 hour."},{"step":3,"instruction":"Shape into balls. Let rest 15 minutes."},{"step":4,"instruction":"Deep fry until golden brown all over. Drain on paper towels."},{"step":5,"instruction":"Serve warm plain, or with butter and jam."}]'),

-- MADAGASCAR
('Ranon''apango', 'Madagascar', 'Africa', true, 'Drinks', 'ranonpango-madagascar',
'Malagasy burnt rice water - a toasty, amber-colored drink made from the crust left in the rice pot.',
'Ranon''apango is uniquely Malagasy, born from the practical tradition of cleaning the rice pot. The burnt rice crust creates a naturally smoky, slightly sweet beverage drunk with every meal.',
'Easy', 5, 10, 4, ARRAY['drinks', 'malagasy', 'rice', 'traditional', 'zero-waste'],
'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=800&auto=format&fit=crop',
'[{"item":"Rice crust (from cooking pot)","quantity":"from 1 pot"},{"item":"Water","quantity":"4 cups"},{"item":"Sugar","quantity":"optional"}]',
'[{"step":1,"instruction":"After cooking rice, leave the browned crust at the bottom of the pot."},{"step":2,"instruction":"Add water to the pot. Heat and scrape the crust loose."},{"step":3,"instruction":"Simmer 5-10 minutes until water turns amber and takes on a toasty flavor."},{"step":4,"instruction":"Strain and serve warm or at room temperature. Add sugar if desired."}]'),

('Romazava', 'Madagascar', 'Africa', true, 'Lunch', 'romazava-madagascar',
'Madagascar''s national dish - beef stew with mixed greens including brèdes and tomatoes.',
'Romazava is considered the national dish of Madagascar. Its name means "clear broth" and it reflects the island''s unique culinary identity, blending African, Asian, and French influences.',
'Easy', 15, 40, 4, ARRAY['lunch', 'malagasy', 'beef', 'greens', 'national-dish'],
'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=800&auto=format&fit=crop',
'[{"item":"Beef","quantity":"500g","note":"cubed"},{"item":"Mixed greens (watercress, spinach, mustard greens)","quantity":"500g"},{"item":"Tomatoes","quantity":"3","note":"diced"},{"item":"Onion","quantity":"1","note":"chopped"},{"item":"Ginger","quantity":"1 inch","note":"grated"},{"item":"Garlic","quantity":"2 cloves"},{"item":"Salt","quantity":"to taste"},{"item":"Rice","quantity":"for serving"}]',
'[{"step":1,"instruction":"Brown beef in a pot. Add onion, garlic, and ginger."},{"step":2,"instruction":"Add tomatoes and 2 cups water. Simmer until beef is tender."},{"step":3,"instruction":"Add mixed greens and cook 5-10 minutes until wilted."},{"step":4,"instruction":"Season with salt. Serve over plenty of white rice."}]'),

('Mofo Gasy', 'Madagascar', 'Africa', true, 'Breakfast', 'mofo-gasy-madagascar',
'Malagasy street breakfast cakes made from rice flour and coconut milk - golden and slightly sweet.',
'Mofo Gasy (Malagasy bread) is the quintessential street breakfast across Madagascar. Cooked on charcoal in special round molds, the sweet aroma fills every morning market.',
'Easy', 15, 15, 8, ARRAY['breakfast', 'malagasy', 'rice', 'coconut', 'street-food'],
'https://images.unsplash.com/photo-1567364816519-cbc9c4a0a736?w=800&auto=format&fit=crop',
'[{"item":"Rice flour","quantity":"2 cups"},{"item":"Coconut milk","quantity":"1 cup"},{"item":"Sugar","quantity":"1/3 cup"},{"item":"Yeast","quantity":"1 tsp"},{"item":"Salt","quantity":"pinch"},{"item":"Oil","quantity":"for cooking"}]',
'[{"step":1,"instruction":"Mix rice flour, sugar, yeast, and salt. Add coconut milk and stir until smooth."},{"step":2,"instruction":"Let rest 30 minutes until slightly bubbly."},{"step":3,"instruction":"Pour into oiled molds or a mini muffin pan."},{"step":4,"instruction":"Cook until golden on both sides."},{"step":5,"instruction":"Serve warm with Malagasy coffee."}]'),

-- MAURITIUS
('Dholl Puri', 'Mauritius', 'Africa', true, 'Lunch', 'dholl-puri-mauritius',
'Mauritian split pea-stuffed flatbread served with bean curry and chutneys - the island''s beloved street lunch.',
'Dholl Puri is Mauritius'' most iconic street food, reflecting the island''s Indian heritage. It is eaten by people of all ethnicities and is considered the great unifier of Mauritian society.',
'Medium', 30, 20, 6, ARRAY['lunch', 'mauritian', 'split-pea', 'flatbread', 'street-food'],
'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=800&auto=format&fit=crop',
