'[{"item":"Milk","quantity":"4 cups"},{"item":"Basil seeds (tukmaria)","quantity":"2 tbsp","note":"soaked"},{"item":"Rose syrup","quantity":"3 tbsp"},{"item":"Agar-agar","quantity":"1 tsp","note":"dissolved and set as jelly"},{"item":"Sugar","quantity":"3 tbsp"},{"item":"Ice","quantity":"plenty"},{"item":"Vanilla extract","quantity":"1 tsp"}]',
'[{"step":1,"instruction":"Soak basil seeds in water for 15 minutes until they swell."},{"step":2,"instruction":"Prepare agar-agar jelly, let set, and cut into small cubes."},{"step":3,"instruction":"Mix cold milk with sugar, rose syrup, and vanilla."},{"step":4,"instruction":"Add drained basil seeds and agar-agar cubes."},{"step":5,"instruction":"Serve over plenty of ice in tall glasses."}]'),

