'[{"step":1,"instruction":"Boil cow skin until tender if using. Set aside."},{"step":2,"instruction":"Blanch waterleaf in boiling water 2 minutes. Drain and squeeze out excess water."},{"step":3,"instruction":"Heat palm oil. Add onion, crayfish, and smoked fish."},{"step":4,"instruction":"Add eru leaves and waterleaf. Stir and cook 20 minutes on low heat."},{"step":5,"instruction":"Add cow skin. Cook 10 more minutes. Serve with garri or fufu."}]'),

('Folere', 'Cameroon', 'Africa', true, 'Drinks', 'folere-cameroon',
