'[{"step":1,"instruction":"Boil hibiscus with ginger and pineapple for 15-20 minutes."},{"step":2,"instruction":"Strain and add sugar. Stir until dissolved."},{"step":3,"instruction":"Cool and refrigerate. Serve cold with mint."}]'),

